"""Use the documented local app-server RPC to reload on-disk MCP configuration."""
import json
import queue
import subprocess
import threading
import time

command=["C:/Users/s0109/AppData/Local/OpenAI/Codex/bin/2993767bd1dfb009/codex.exe","app-server","proxy"]
process=subprocess.Popen(command,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
    encoding="utf-8",text=True,creationflags=subprocess.CREATE_NO_WINDOW)
responses,errors=queue.Queue(),[]
def reader():
    for line in process.stdout:
        try: responses.put(json.loads(line))
        except json.JSONDecodeError: errors.append("Invalid JSON response")
def stderr():
    for line in process.stderr: errors.append(line[:1000])
threading.Thread(target=reader,daemon=True).start()
threading.Thread(target=stderr,daemon=True).start()
def send(message):
    process.stdin.write(json.dumps(message)+"\n")
    process.stdin.flush()
def request(identifier,method,params):
    send(dict(id=identifier,method=method,params=params))
    deadline=time.monotonic()+20
    while time.monotonic()<deadline:
        try: response=responses.get(timeout=.2)
        except queue.Empty:
            if process.poll() is not None: raise RuntimeError("Proxy exited: "+str(errors))
            continue
        if response.get("id")==identifier: return response
    raise TimeoutError(method+" did not respond")
try:
    initialized=request(1,"initialize",dict(clientInfo=dict(name="local-kernel-repair",version="1")))
    if "error" in initialized: raise RuntimeError(str(initialized["error"]))
    send(dict(method="initialized"))
    loaded=request(2,"thread/loaded/list",dict(limit=100))
    print(json.dumps(dict(initialized=True,loaded_threads_count=len(loaded.get("result",{}).get("data",[]))),ensure_ascii=False))
    response=request(3,"config/mcpServer/reload",None)
    print(json.dumps(dict(method="config/mcpServer/reload",response=response),ensure_ascii=False))
finally:
    if process.poll() is None:
        process.stdin.close()
        try: process.wait(timeout=3)
        except subprocess.TimeoutExpired:
            process.terminate()
            process.wait(timeout=3)
    if errors: print(json.dumps(dict(proxy_stderr=errors[-3:]),ensure_ascii=False))
